package com.vault.controller;import com.vault.dto.*;import com.vault.service.KeyService;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/keys")public class ApiKeyController{private final KeyService service;public ApiKeyController(KeyService s){service=s;}@GetMapping public List<Views.KeyView> list(Authentication a){return service.list(a.getName());}@PostMapping@ResponseStatus(HttpStatus.CREATED)public Views.KeyView create(Authentication a,@Valid @RequestBody Requests.CreateKey x){return service.create(a.getName(),x);}@GetMapping("/{id}")public Views.KeyView get(Authentication a,@PathVariable UUID id){return service.get(a.getName(),id);}@PutMapping("/{id}")public Views.KeyView update(Authentication a,@PathVariable UUID id,@Valid @RequestBody Requests.UpdateKey x){return service.update(a.getName(),id,x);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(Authentication a,@PathVariable UUID id){service.delete(a.getName(),id);}@PostMapping("/{id}/reveal")public Map<String,String> reveal(Authentication a,@PathVariable UUID id,@Valid @RequestBody Requests.Reveal x){return Map.of("apiKey",service.reveal(a.getName(),id,x));}@PostMapping("/{id}/rotate")public Views.KeyView rotate(Authentication a,@PathVariable UUID id,@Valid @RequestBody Requests.Rotate x){return service.rotate(a.getName(),id,x);}@PostMapping("/{id}/revoke")@ResponseStatus(HttpStatus.NO_CONTENT)public void revoke(Authentication a,@PathVariable UUID id){service.revoke(a.getName(),id);}@PostMapping("/{id}/copy")@ResponseStatus(HttpStatus.NO_CONTENT)public void copy(Authentication a,@PathVariable UUID id){service.copy(a.getName(),id);}}
